    if (nextOwned[row.sceneName]?.geometry !== geometry(row)) await call('SetSceneItemTransform', { sceneName: row.sceneName, sceneItemId, sceneItemTransform: { positionX: row.x, positionY: row.y, alignment: 5, boundsAlignment: 5, boundsType: 'OBS_BOUNDS_STRETCH', boundsWidth: row.width, boundsHeight: row.height } });
    nextOwned[row.sceneName] = { inputName, geometry: geometry(row), background: row.background, backgroundItem }; saveOwned(nextOwned);
    prepared.push(row.sceneName);
